code.src:
.card:has(img)        { padding: 0; }
.card:not(:has(img))  { padding: 16px; }

/* フォームに不正な入力があるときだけカードを赤枠 */
.card:has(:invalid) {
  outline: 2px solid red;
}

/* 入力にフォーカスが当たっているラベルを強調 */
label:has(+ input:focus) { color: var(--color-primary); }

/* チェック済みカードを強調 */
.choice:has(> input:checked) {
  background: #e6f7ff;
  border-color: var(--color-primary);
}

/* ❌ ID が混じると詳細度が跳ね上がる */
.section:has(#hero) { background: red; }

/* ✅ クラスだけで保つ */
.section:has(.hero) { background: red; }

/* 送信ボタンを、フォームにエラーがあるとき無効化見た目に */
form:has(.error) button[type='submit'] {
  opacity: 0.5;
  pointer-events: none;
}
